        for i in range ( gap, len ( seq ) ) : 
            temp = seq [ i ] 
            j = i 
            while j > gap and seq [ j - gap ] > temp : 
                seq [ j ] = seq [ j - gap ] 
                j -= 1 
            seq [ j ] = temp 
    return seq

